  g.P3_YEAR_PLAN = {"learnGuide":{"en":"Read the word aloud, check the Chinese meaning, compare it with the basic word it replaces, and read the example sentence. Then try making one spoken or written sentence of your own.","zh":"大聲讀出詞語，看看中文意思，和它可以替代的基礎詞比較，讀例句，然後試造一句（口說或書寫都可以）。"},"learnGuideSat":{"en":"Cover the English column and test yourself using the Chinese translations, or play a quick matching/acting game with a parent.","zh":"遮住英文欄，用中文自測，或跟家長玩配對／表演小遊戲。"},"learnGuideSun":{"en":"Write a short paragraph (3–5 sentences) using at least 3 of the week's words/phrases based on the weekly prompt.","zh":"按本週提示，用最少 3 個本週詞語寫一段 3–5 句英文。"},"weeks":[{"week":1,"weekTitle":"Happy & Good (開心與美好)","learn":[{"weekday":"Mon","title":"delighted","pos":"adj.","meaning":"非常高興的；欣喜的","example":"I was delighted to receive a new bicycle for my birthday.","upgradeFrom":"very happy"},{"weekday":"Tue","title":"thrilled","pos":"adj.","meaning":"興奮不已的；激動的","example":"Sam was thrilled when his teacher chose him as the class monitor.","upgradeFrom":"very excited"},{"weekday":"Wed","title":"cheerful","pos":"adj.","meaning":"開朗的；快樂的","example":"Our neighbour is a cheerful lady who always greets us with a smile.","upgradeFrom":"happy"},{"weekday":"Thu","title":"wonderful","pos":"adj.","meaning":"極好的；精彩的","example":"We had a wonderful time building sandcastles at the beach.","upgradeFrom":"very good"},{"weekday":"Fri","title":"fantastic","pos":"adj.","meaning":"了不起的；極棒的","example":"Mum cooked a fantastic dinner to celebrate Grandpa's birthday.","upgradeFrom":"great"}],"review":{"task":"Read all 5 words aloud and spell each one twice.","weekWords":["delighted","thrilled","cheerful","wonderful","fantastic"]},"writing":{"task":"Write 3–4 sentences about a happy weekend outing with your family.","weekWords":["delighted","thrilled","cheerful","wonderful","fantastic"]}},{"week":2,"weekTitle":"Sad, Angry & Scared (傷心、生氣與害怕)","learn":[{"weekday":"Mon","title":"disappointed","pos":"adj.","meaning":"失望的","example":"Amy felt disappointed because the picnic was cancelled due to rain.","upgradeFrom":"sad"},{"weekday":"Tue","title":"miserable","pos":"adj.","meaning":"悲慘的；十分難過的","example":"The little puppy looked miserable sitting alone in the rain.","upgradeFrom":"very sad"},{"weekday":"Wed","title":"furious","pos":"adj.","meaning":"暴怒的；極度生氣的","example":"Dad was furious when he saw muddy footprints on the clean sofa.","upgradeFrom":"very angry"},{"weekday":"Thu","title":"frightened","pos":"adj.","meaning":"受驚的；害怕的","example":"The frightened kitten hid under the bed during the thunderstorm.","upgradeFrom":"scared"},{"weekday":"Fri","title":"anxious","pos":"adj.","meaning":"焦慮的；擔心的","example":"Tom felt anxious before going on stage for the speech competition.","upgradeFrom":"worried"}],"review":{"task":"Act out each emotion in front of a mirror and say the English word.","weekWords":["disappointed","miserable","furious","frightened","anxious"]},"writing":{"task":"Write 3–4 sentences about a time something went wrong at school or home.","weekWords":["disappointed","miserable","furious","frightened","anxious"]}},{"week":3,"weekTitle":"Size & Appearance (大小與外觀)","learn":[{"weekday":"Mon","title":"enormous","pos":"adj.","meaning":"龐大的；巨大的","example":"An enormous whale leaped out of the blue ocean.","upgradeFrom":"very big"},{"weekday":"Tue","title":"tiny","pos":"adj.","meaning":"極小的；微小的","example":"I spotted a tiny ladybug resting on a green leaf.","upgradeFrom":"very small"},{"weekday":"Wed","title":"spotless","pos":"adj.","meaning":"一塵不染的；非常乾淨的","example":"After an hour of tidying up, my bedroom was spotless.","upgradeFrom":"very clean"},{"weekday":"Thu","title":"filthy","pos":"adj.","meaning":"骯髒不堪的","example":"Ben's football jersey was filthy after playing in the mud.","upgradeFrom":"very dirty"},{"weekday":"Fri","title":"gorgeous","pos":"adj.","meaning":"華麗的；極美的","example":"We watched a gorgeous sunset from the top of the hill.","upgradeFrom":"very pretty"}],"review":{"task":"Find one object at home that matches each adjective (or draw it).","weekWords":["enormous","tiny","spotless","filthy","gorgeous"]},"writing":{"task":"Describe your favourite park or room in 4 sentences using at least 3 new words.","weekWords":["enormous","tiny","spotless","filthy","gorgeous"]}},{"week":4,"weekTitle":"Weather & Temperature (天氣與溫度)","learn":[{"weekday":"Mon","title":"scorching","pos":"adj.","meaning":"酷熱的；炎熱的","example":"We ate ice cream to cool down on the scorching summer afternoon.","upgradeFrom":"very hot"},{"weekday":"Tue","title":"freezing","pos":"adj.","meaning":"冰冷的；極冷的","example":"Put on your scarf and gloves because it is freezing outside!","upgradeFrom":"very cold"},{"weekday":"Wed","title":"chilly","pos":"adj.","meaning":"微冷的；寒涼的","example":"A chilly wind blew through the open window in the morning.","upgradeFrom":"a bit cold"},{"weekday":"Thu","title":"drenched","pos":"adj.","meaning":"濕透的","example":"I forgot my umbrella and arrived home completely drenched.","upgradeFrom":"very wet"},{"weekday":"Fri","title":"breezy","pos":"adj.","meaning":"微風習習的","example":"It was a breezy autumn day, perfect for flying kites.","upgradeFrom":"nicely windy"}],"review":{"task":"Sort the 5 words from hottest to coldest/wettest and recite them.","weekWords":["scorching","freezing","chilly","drenched","breezy"]},"writing":{"task":"Write a short diary entry about a day with unexpected weather.","weekWords":["scorching","freezing","chilly","drenched","breezy"]}},{"week":5,"weekTitle":"Ways of Moving (不同的移動方式)","learn":[{"weekday":"Mon","title":"stroll","pos":"v.","meaning":"散步；悠閒地走","example":"My grandparents like to stroll in the park after dinner.","upgradeFrom":"walk slowly"},{"weekday":"Tue","title":"sprint","pos":"v.","meaning":"全力衝刺；飛奔","example":"Leo had to sprint to catch the school bus before it left.","upgradeFrom":"run very fast"},{"weekday":"Wed","title":"tiptoe","pos":"v.","meaning":"躡手躡腳地走","example":"I tiptoed into the living room so I would not wake the baby.","upgradeFrom":"walk quietly"},{"weekday":"Thu","title":"dash","pos":"v.","meaning":"猛衝；急奔","example":"When the recess bell rang, the students dashed to the playground.","upgradeFrom":"run quickly"},{"weekday":"Fri","title":"wander","pos":"v.","meaning":"漫步；遊蕩","example":"We wandered around the night market looking at colourful stalls.","upgradeFrom":"walk around"}],"review":{"task":"Physically act out all 5 verbs around the room!","weekWords":["stroll","sprint","tiptoe","dash","wander"]},"writing":{"task":"Write 4 sentences describing your journey to school or a busy playground scene.","weekWords":["stroll","sprint","tiptoe","dash","wander"]}},{"week":6,"weekTitle":"Ways of Speaking (不同的說話方式)","learn":[{"weekday":"Mon","title":"whisper","pos":"v.","meaning":"低聲說；耳語","example":"\"Don't tell anyone the secret,\" Lily whispered to her best friend.","upgradeFrom":"say quietly"},{"weekday":"Tue","title":"exclaim","pos":"v.","meaning":"驚呼；大聲說出","example":"\"What a huge rainbow!\" Tim exclaimed as he pointed to the sky.","upgradeFrom":"say excitedly"},{"weekday":"Wed","title":"mumble","pos":"v.","meaning":"咕噥；含糊地說","example":"Jack mumbled an apology while looking down at his shoes.","upgradeFrom":"say unclearly"},{"weekday":"Thu","title":"yell","pos":"v.","meaning":"大喊；叫嚷","example":"The coach yelled instructions from the side of the pitch.","upgradeFrom":"shout loudly"},{"weekday":"Fri","title":"beg","pos":"v.","meaning":"懇求；乞求","example":"The children begged their parents to stay ten more minutes at the zoo.","upgradeFrom":"ask strongly"}],"review":{"task":"Say the sentence \"Look over there!\" in all 5 different ways.","weekWords":["whisper","exclaim","mumble","yell","beg"]},"writing":{"task":"Write a short dialogue between two friends using at least 3 speaking verbs instead of \"said\".","weekWords":["whisper","exclaim","mumble","yell","beg"]}},{"week":7,"weekTitle":"Ways of Looking (不同的看的方式)","learn":[{"weekday":"Mon","title":"glance","pos":"v.","meaning":"瞥見；匆匆一看","example":"She glanced at her watch and realised she was late.","upgradeFrom":"look quickly"},{"weekday":"Tue","title":"stare","pos":"v.","meaning":"盯著看；凝視","example":"The boy stared in amazement at the magician's floating hat.","upgradeFrom":"look for a long time"},{"weekday":"Wed","title":"peek","pos":"v.","meaning":"偷看；窺視","example":"Curious about his gift, Max peeked inside the shopping bag.","upgradeFrom":"look secretly"},{"weekday":"Thu","title":"notice","pos":"v.","meaning":"注意到；察覺","example":"Did you notice the new poster hanging on the classroom wall?","upgradeFrom":"see"},{"weekday":"Fri","title":"spot","pos":"v.","meaning":"發現；認出","example":"From the bus window, I spotted my favourite bakery.","upgradeFrom":"find by looking"}],"review":{"task":"Quiz yourself: Which verb means \"look secretly\"? Which means \"look quickly\"?","weekWords":["glance","stare","peek","notice","spot"]},"writing":{"task":"Write 4 sentences about discovering something surprising in your neighbourhood.","weekWords":["glance","stare","peek","notice","spot"]}},{"week":8,"weekTitle":"Eating & Drinking (吃與喝的生動動詞)","learn":[{"weekday":"Mon","title":"gobble up","pos":"phr. v.","meaning":"狼吞虎嚥地吃光","example":"After swimming class, Ryan gobbled up two bowls of noodles.","upgradeFrom":"eat very fast"},{"weekday":"Tue","title":"nibble","pos":"v.","meaning":"小口咬；輕咬","example":"The hamster nibbled happily on a piece of carrot.","upgradeFrom":"eat tiny bites"},{"weekday":"Wed","title":"devour","pos":"v.","meaning":"大口吞食；貪婪地吃","example":"The hungry hikers devoured their sandwiches at the summit.","upgradeFrom":"eat hungrily"},{"weekday":"Thu","title":"sip","pos":"v.","meaning":"小口啜飲","example":"Mum sipped her hot lemon tea while reading the newspaper.","upgradeFrom":"drink slowly"},{"weekday":"Fri","title":"gulp down","pos":"phr. v.","meaning":"大口喝下","example":"After running a race, I gulped down a whole bottle of water.","upgradeFrom":"drink very fast"}],"review":{"task":"Match each verb to a food or drink (e.g., hot soup -> sip).","weekWords":["gobble up","nibble","devour","sip","gulp down"]},"writing":{"task":"Write 4 sentences describing a family meal or a picnic lunch.","weekWords":["gobble up","nibble","devour","sip","gulp down"]}},{"week":9,"weekTitle":"Positive Personalities (正面性格)","learn":[{"weekday":"Mon","title":"generous","pos":"adj.","meaning":"慷慨的；大方的","example":"My generous cousin shared all his snacks with us.","upgradeFrom":"kind (sharing)"},{"weekday":"Tue","title":"considerate","pos":"adj.","meaning":"體貼的；為他人著想的","example":"It was considerate of Grace to hold the lift door for the elderly man.","upgradeFrom":"nice / caring"},{"weekday":"Wed","title":"courageous","pos":"adj.","meaning":"勇敢的；無畏的","example":"The courageous firefighter rescued the trapped cat from the tree.","upgradeFrom":"very brave"},{"weekday":"Thu","title":"diligent","pos":"adj.","meaning":"勤奮的；用功的","example":"Eva is a diligent student who revises her notes every evening.","upgradeFrom":"hardworking"},{"weekday":"Fri","title":"humble","pos":"adj.","meaning":"謙虛的","example":"Even though he won first prize, Owen remained polite and humble.","upgradeFrom":"not boastful"}],"review":{"task":"Name one person (real or from a storybook) for each personality trait.","weekWords":["generous","considerate","courageous","diligent","humble"]},"writing":{"task":"Write a short paragraph describing your best friend or a family member you admire.","weekWords":["generous","considerate","courageous","diligent","humble"]}},{"week":10,"weekTitle":"Challenging Personalities (負面或特別性格)","learn":[{"weekday":"Mon","title":"stubborn","pos":"adj.","meaning":"固執的；倔強的","example":"The stubborn donkey refused to move an inch down the path.","upgradeFrom":"refuses to listen"},{"weekday":"Tue","title":"clumsy","pos":"adj.","meaning":"笨手笨腳的","example":"I felt so clumsy when I accidentally knocked over my glass of milk.","upgradeFrom":"drops things easily"},{"weekday":"Wed","title":"impatient","pos":"adj.","meaning":"沒耐性的；急躁的","example":"The impatient boy kept tapping his foot in the long queue.","upgradeFrom":"cannot wait"},{"weekday":"Thu","title":"greedy","pos":"adj.","meaning":"貪心的；貪吃的","example":"The greedy fox tried to take all the grapes for itself.","upgradeFrom":"wants too much"},{"weekday":"Fri","title":"mischievous","pos":"adj.","meaning":"淘氣的；愛惡作劇的","example":"Our mischievous puppy hid Dad's slippers under the couch.","upgradeFrom":"naughty (playful)"}],"review":{"task":"Read the spelling of *mischievous* and *impatient* carefully three times.","weekWords":["stubborn","clumsy","impatient","greedy","mischievous"]},"writing":{"task":"Write 4 sentences about a funny or naughty character (a pet or storybook animal).","weekWords":["stubborn","clumsy","impatient","greedy","mischievous"]}},{"week":11,"weekTitle":"Facial Expressions & Body Language (表情與肢體語言)","learn":[{"weekday":"Mon","title":"grin from ear to ear","pos":"phr.","meaning":"笑得合不攏嘴","example":"Ken grinned from ear to ear when he saw his A+ test paper.","upgradeFrom":"smile very widely"},{"weekday":"Tue","title":"frown","pos":"v.","meaning":"皺眉","example":"Miss Chan frowned when she saw the messy desks.","upgradeFrom":"look unhappy/confused"},{"weekday":"Wed","title":"shrug one's shoulders","pos":"phr.","meaning":"聳聳肩","example":"Mia shrugged her shoulders because she had no idea where the key was.","upgradeFrom":"say \"I don't know\""},{"weekday":"Thu","title":"tremble with fear","pos":"phr.","meaning":"嚇得發抖","example":"The little rabbit trembled with fear as the eagle flew overhead.","upgradeFrom":"shake because scared"},{"weekday":"Fri","title":"blush","pos":"v.","meaning":"臉紅","example":"Andy blushed when the whole class sang \"Happy Birthday\" to him.","upgradeFrom":"turn red (shy)"}],"review":{"task":"Show each facial expression/gesture while saying the English phrase.","weekWords":["grin from ear to ear","frown","shrug one's shoulders","tremble with fear","blush"]},"writing":{"task":"Write a short scene showing how a character feels WITHOUT using the words *happy, sad, angry,* or *scared*.","weekWords":["grin from ear to ear","frown","shrug one's shoulders","tremble with fear","blush"]}},{"week":12,"weekTitle":"Friendship & Relationships (友誼與人際關係)","learn":[{"weekday":"Mon","title":"get along well with","pos":"phr.","meaning":"與……相處融洽","example":"I get along well with my new classmate because we both love drawing.","upgradeFrom":"be good friends with"},{"weekday":"Tue","title":"encourage","pos":"v.","meaning":"鼓勵","example":"My parents always encourage me to try my best.","upgradeFrom":"cheer up / support"},{"weekday":"Wed","title":"comfort","pos":"v.","meaning":"安慰","example":"Chloe hugged her crying sister to comfort her.","upgradeFrom":"make feel better"},{"weekday":"Thu","title":"trustworthy","pos":"adj.","meaning":"值得信賴的","example":"Leo is a trustworthy friend who always keeps his promises.","upgradeFrom":"honest / reliable"},{"weekday":"Fri","title":"admire","pos":"v.","meaning":"欽佩；欣賞","example":"I deeply admire doctors and nurses for helping sick people.","upgradeFrom":"like and respect"}],"review":{"task":"Make one true sentence about your own life for each word/phrase.","weekWords":["get along well with","encourage","comfort","trustworthy","admire"]},"writing":{"task":"Write 4–5 sentences about a time a friend or family member helped you.","weekWords":["get along well with","encourage","comfort","trustworthy","admire"]}},{"week":13,"weekTitle":"In the Classroom (課室裡)","learn":[{"weekday":"Mon","title":"pay close attention","pos":"phr.","meaning":"專心致志；密切注意","example":"We must pay close attention during the science experiment.","upgradeFrom":"listen carefully"},{"weekday":"Tue","title":"curious","pos":"adj.","meaning":"好奇的","example":"The curious students asked many questions about outer space.","upgradeFrom":"want to know"},{"weekday":"Wed","title":"puzzled","pos":"adj.","meaning":"困惑的；百思不得其解的","example":"I looked puzzled because the last maths question was very tricky.","upgradeFrom":"confused"},{"weekday":"Thu","title":"eager","pos":"adj.","meaning":"渴望的；熱切的","example":"Everyone was eager to open the new art supplies box.","upgradeFrom":"very keen / excited"},{"weekday":"Fri","title":"concentrate","pos":"v.","meaning":"集中精神；專注","example":"Please stay quiet so I can concentrate on my writing.","upgradeFrom":"focus"}],"review":{"task":"Spell *curious*, *puzzled*, and *concentrate* from memory.","weekWords":["pay close attention","curious","puzzled","eager","concentrate"]},"writing":{"task":"Write 4 sentences about your favourite lesson at school.","weekWords":["pay close attention","curious","puzzled","eager","concentrate"]}},{"week":14,"weekTitle":"Effort & Study Habits (努力與學習習慣)","learn":[{"weekday":"Mon","title":"make progress","pos":"phr.","meaning":"取得進步","example":"With daily practice, Daniel is making progress in playing the piano.","upgradeFrom":"get better"},{"weekday":"Tue","title":"revise","pos":"v.","meaning":"溫習；複習","example":"I always revise my spelling list before the dictation.","upgradeFrom":"study again"},{"weekday":"Wed","title":"put in effort","pos":"phr.","meaning":"付出努力","example":"If you put in effort, you will surely succeed.","upgradeFrom":"work hard"},{"weekday":"Thu","title":"improve","pos":"v.","meaning":"改善；提升","example":"Reading storybooks every night helps improve my vocabulary.","upgradeFrom":"make better"},{"weekday":"Fri","title":"determined","pos":"adj.","meaning":"堅決的；下定決心的","example":"Hannah was determined to finish the jigsaw puzzle by herself.","upgradeFrom":"will not give up"}],"review":{"task":"Review the collocations: *make* progress, *put in* effort.","weekWords":["make progress","revise","put in effort","improve","determined"]},"writing":{"task":"Write 4 sentences about a skill you want to get better at this year.","weekWords":["make progress","revise","put in effort","improve","determined"]}},{"week":15,"weekTitle":"Sports Day & Recess (運動日與小息)","learn":[{"weekday":"Mon","title":"exhausted","pos":"adj.","meaning":"筋疲力盡的","example":"After running the 100-metre race, I felt completely exhausted.","upgradeFrom":"very tired"},{"weekday":"Tue","title":"cheer someone on","pos":"phr.","meaning":"為某人打氣加油","example":"Our classmates waved flags to cheer the relay runners on.","upgradeFrom":"shout for someone"},{"weekday":"Wed","title":"energetic","pos":"adj.","meaning":"精力充沛的；充滿活力的","example":"The energetic boys played basketball during the entire recess.","upgradeFrom":"full of energy"},{"weekday":"Thu","title":"compete","pos":"v.","meaning":"競爭；參加比賽","example":"Thirty students will compete in the school swimming gala.","upgradeFrom":"race / join a game"},{"weekday":"Fri","title":"triumph","pos":"n.","meaning":"勝利；成功","example":"Raising the trophy was a moment of great triumph for our team.","upgradeFrom":"big win"}],"review":{"task":"Translate all 5 words from Chinese back into English.","weekWords":["exhausted","cheer someone on","energetic","compete","triumph"]},"writing":{"task":"Write a short paragraph about a thrilling Sports Day or PE lesson.","weekWords":["exhausted","cheer someone on","energetic","compete","triumph"]}},{"week":16,"weekTitle":"Teamwork & School Events (團隊合作與校園活動)","learn":[{"weekday":"Mon","title":"cooperate","pos":"v.","meaning":"合作；配合","example":"Our group cooperated well to build a tall paper tower.","upgradeFrom":"work together"},{"weekday":"Tue","title":"participate in","pos":"phr.","meaning":"參加；參與","example":"I am excited to participate in the charity walk next month.","upgradeFrom":"join"},{"weekday":"Wed","title":"creative","pos":"adj.","meaning":"有創意的","example":"Emma had a creative idea to make a robot out of recycled boxes.","upgradeFrom":"full of good ideas"},{"weekday":"Thu","title":"rehearse","pos":"v.","meaning":"排練；綵排","example":"The school choir rehearsed the song every afternoon before the concert.","upgradeFrom":"practise for a show"},{"weekday":"Fri","title":"applaud","pos":"v.","meaning":"鼓掌喝采","example":"The audience applauded loudly at the end of the puppet show.","upgradeFrom":"clap hands"}],"review":{"task":"Check the preposition: participate **in** (not *at*).","weekWords":["cooperate","participate in","creative","rehearse","applaud"]},"writing":{"task":"Write 4 sentences about a school concert, Open Day, or group project.","weekWords":["cooperate","participate in","creative","rehearse","applaud"]}},{"week":17,"weekTitle":"Achievements & Mistakes (成就與錯誤)","learn":[{"weekday":"Mon","title":"proud of","pos":"phr.","meaning":"為……感到自豪","example":"My parents were proud of me for winning the painting award.","upgradeFrom":"happy about success"},{"weekday":"Tue","title":"careless","pos":"adj.","meaning":"粗心的；疏忽的","example":"I lost five marks because of a careless spelling mistake.","upgradeFrom":"not careful"},{"weekday":"Wed","title":"accomplish","pos":"v.","meaning":"完成；達成","example":"We felt joyful after accomplishing the challenging hiking trail.","upgradeFrom":"finish (a goal)"},{"weekday":"Thu","title":"regret","pos":"v.","meaning":"後悔；遺憾","example":"Tim regretted staying up late to play video games before the exam.","upgradeFrom":"feel sorry about"},{"weekday":"Fri","title":"overcome","pos":"v.","meaning":"克服；戰勝","example":"With practice, Sophie overcame her fear of speaking in public.","upgradeFrom":"beat (a problem)"}],"review":{"task":"Pair up the opposites/contrasts: *proud of* vs *regret*, *careless* vs *diligent* (from Week 9).","weekWords":["proud of","careless","accomplish","regret","overcome"]},"writing":{"task":"Write 4 sentences about a mistake you made and how you fixed it.","weekWords":["proud of","careless","accomplish","regret","overcome"]}},{"week":18,"weekTitle":"Chores & Helping at Home (家務與幫忙)","learn":[{"weekday":"Mon","title":"tidy up","pos":"phr. v.","meaning":"整理；收拾","example":"Please tidy up your toys before Grandma arrives.","upgradeFrom":"clean up"},{"weekday":"Tue","title":"lend a hand","pos":"phr.","meaning":"伸出援手；幫忙","example":"I offered to lend a hand when Mum was carrying heavy grocery bags.","upgradeFrom":"help"},{"weekday":"Wed","title":"responsible","pos":"adj.","meaning":"有責任感的","example":"Feeding the goldfish every morning makes me feel responsible.","upgradeFrom":"reliable / does duty"},{"weekday":"Thu","title":"organise","pos":"v.","meaning":"整理；安排妥當","example":"On Sunday, I organised my bookshelves by colour and size.","upgradeFrom":"put in order"},{"weekday":"Fri","title":"chore","pos":"n.","meaning":"家務事；日常雜務","example":"Washing the dishes after dinner is my favourite chore.","upgradeFrom":"housework job"}],"review":{"task":"Use *lend a hand* and *chore* together in one spoken sentence.","weekWords":["tidy up","lend a hand","responsible","organise","chore"]},"writing":{"task":"Write 4 sentences about how you help your family at home on weekends.","weekWords":["tidy up","lend a hand","responsible","organise","chore"]}},{"week":19,"weekTitle":"Food & Taste (美食與味道)","learn":[{"weekday":"Mon","title":"mouth-watering","pos":"adj.","meaning":"令人垂涎三尺的","example":"A mouth-watering aroma of roast chicken filled the kitchen.","upgradeFrom":"looks/smells delicious"},{"weekday":"Tue","title":"crispy","pos":"adj.","meaning":"香脆的；酥脆的","example":"These freshly baked egg tarts have a golden, crispy crust.","upgradeFrom":"crunchy"},{"weekday":"Wed","title":"nutritious","pos":"adj.","meaning":"有營養的","example":"Eating nutritious vegetables helps us grow strong and tall.","upgradeFrom":"healthy (food)"},{"weekday":"Thu","title":"bland","pos":"adj.","meaning":"清淡無味的","example":"The soup tasted a bit bland, so Dad added a pinch of salt.","upgradeFrom":"tasteless"},{"weekday":"Fri","title":"feast","pos":"n.","meaning":"盛宴；豐盛的大餐","example":"Grandma prepared a wonderful feast for Lunar New Year's Eve.","upgradeFrom":"big, special meal"}],"review":{"task":"Name one food for each adjective: *mouth-watering, crispy, nutritious, bland*.","weekWords":["mouth-watering","crispy","nutritious","bland","feast"]},"writing":{"task":"Describe your favourite meal or restaurant visit in 4–5 sentences.","weekWords":["mouth-watering","crispy","nutritious","bland","feast"]}},{"week":20,"weekTitle":"Celebrations & Festivals (慶祝與節日)","learn":[{"weekday":"Mon","title":"festive","pos":"adj.","meaning":"充滿節日氣氛的","example":"The streets looked festive with glowing lanterns everywhere.","upgradeFrom":"holiday-like / joyful"},{"weekday":"Tue","title":"decorate","pos":"v.","meaning":"裝飾；佈置","example":"My brother and I decorated the living room with colourful balloons.","upgradeFrom":"make pretty"},{"weekday":"Wed","title":"gather","pos":"v.","meaning":"聚集；聚會","example":"Our relatives gathered around the table to share mooncakes.","upgradeFrom":"come together"},{"weekday":"Thu","title":"tradition","pos":"n.","meaning":"傳統；習俗","example":"Giving red packets is an important tradition during Chinese New Year.","upgradeFrom":"old custom"},{"weekday":"Fri","title":"unforgettable","pos":"adj.","meaning":"令人難忘的","example":"Watching the fireworks over the harbour was an unforgettable experience.","upgradeFrom":"cannot forget"}],"review":{"task":"Spell *decorate* and *unforgettable* without looking.","weekWords":["festive","decorate","gather","tradition","unforgettable"]},"writing":{"task":"Write a short paragraph about your favourite festival of the year.","weekWords":["festive","decorate","gather","tradition","unforgettable"]}},{"week":21,"weekTitle":"Weekend Outings (週末外出)","learn":[{"weekday":"Mon","title":"crowded","pos":"adj.","meaning":"擁擠的；人山人海的","example":"The MTR station was very crowded on Saturday afternoon.","upgradeFrom":"full of people"},{"weekday":"Tue","title":"amusing","pos":"adj.","meaning":"有趣的；逗人發笑的","example":"We watched an amusing cartoon at the cinema.","upgradeFrom":"funny"},{"weekday":"Wed","title":"souvenir","pos":"n.","meaning":"紀念品","example":"I bought a panda keychain as a souvenir from Ocean Park.","upgradeFrom":"holiday gift"},{"weekday":"Thu","title":"explore","pos":"v.","meaning":"探索；探險","example":"We spent the afternoon exploring the science museum.","upgradeFrom":"look around new places"},{"weekday":"Fri","title":"fascinating","pos":"adj.","meaning":"迷人的；極有趣的","example":"The dinosaur skeletons in the exhibition were fascinating.","upgradeFrom":"very interesting"}],"review":{"task":"Practise pronouncing *souvenir* (/ˌsuː.vəˈnɪər/) and *fascinating*.","weekWords":["crowded","amusing","souvenir","explore","fascinating"]},"writing":{"task":"Write a diary entry about a fun place you visited recently.","weekWords":["crowded","amusing","souvenir","explore","fascinating"]}},{"week":22,"weekTitle":"Parks & Scenery (公園與風景)","learn":[{"weekday":"Mon","title":"breathtaking","pos":"adj.","meaning":"令人屏息的；壯麗的","example":"The view of the mountains from the cable car was breathtaking.","upgradeFrom":"super beautiful (view)"},{"weekday":"Tue","title":"peaceful","pos":"adj.","meaning":"寧靜的；和平的","example":"Sitting beside the quiet pond felt so peaceful.","upgradeFrom":"quiet and calm"},{"weekday":"Wed","title":"crystal-clear","pos":"adj.","meaning":"清澈見底的","example":"We could see tiny silver fish swimming in the crystal-clear stream.","upgradeFrom":"very clear (water)"},{"weekday":"Thu","title":"lush","pos":"adj.","meaning":"茂盛的；鬱鬱蔥蔥的","example":"The hiking trail wound through a lush green forest.","upgradeFrom":"very green and thick"},{"weekday":"Fri","title":"bloom","pos":"v.","meaning":"開花；綻放","example":"Pink cherry blossoms begin to bloom in early spring.","upgradeFrom":"open (flowers)"}],"review":{"task":"Close your eyes and picture a scene containing all 5 words.","weekWords":["breathtaking","peaceful","crystal-clear","lush","bloom"]},"writing":{"task":"Describe a countryside park, beach, or hiking trail in 4 sentences.","weekWords":["breathtaking","peaceful","crystal-clear","lush","bloom"]}},{"week":23,"weekTitle":"Animals & Pets (動物與寵物)","learn":[{"weekday":"Mon","title":"adorable","pos":"adj.","meaning":"可愛得令人疼愛的","example":"The adorable baby panda rolled down the grassy hill.","upgradeFrom":"very cute"},{"weekday":"Tue","title":"fierce","pos":"adj.","meaning":"兇猛的","example":"A fierce tiger roared loudly inside its enclosure.","upgradeFrom":"very angry/scary (animal)"},{"weekday":"Wed","title":"loyal","pos":"adj.","meaning":"忠誠的；忠心的","example":"Dogs are known to be loyal companions to humans.","upgradeFrom":"always stays by your side"},{"weekday":"Thu","title":"clever","pos":"adj.","meaning":"聰明的；機靈的","example":"The clever dolphin balanced a ball on its nose.","upgradeFrom":"smart"},{"weekday":"Fri","title":"creature","pos":"n.","meaning":"生物；動物","example":"The deep ocean is home to many mysterious sea creatures.","upgradeFrom":"animal / living thing"}],"review":{"task":"Match an animal to each word (*adorable, fierce, loyal, clever*).","weekWords":["adorable","fierce","loyal","clever","creature"]},"writing":{"task":"Write 4–5 sentences about your dream pet or a memorable trip to the zoo.","weekWords":["adorable","fierce","loyal","clever","creature"]}},{"week":24,"weekTitle":"Storms & Changing Weather (風暴與多變的天氣)","learn":[{"weekday":"Mon","title":"pour down","pos":"phr. v.","meaning":"傾盆而下","example":"Suddenly, dark clouds covered the sky and rain began to pour down.","upgradeFrom":"rain heavily"},{"weekday":"Tue","title":"howl","pos":"v.","meaning":"呼嘯；怒號（風聲）","example":"During the typhoon, the strong wind howled outside our flat.","upgradeFrom":"blow loudly"},{"weekday":"Wed","title":"flash","pos":"v.","meaning":"閃現；閃耀","example":"Bright lightning flashed across the dark night sky.","upgradeFrom":"shine suddenly"},{"weekday":"Thu","title":"rumble","pos":"v.","meaning":"隆隆作響（雷聲）","example":"Thunder rumbled in the distance, warning us of a storm.","upgradeFrom":"make a deep sound"},{"weekday":"Fri","title":"clear up","pos":"phr. v.","meaning":"放晴；轉晴","example":"Luckily, the sky cleared up just in time for our barbecue.","upgradeFrom":"stop raining"}],"review":{"task":"Review which verb matches which nature noun: rain (*pour down*), wind (*howl*), lightning (*flash*), thunder (*rumble*).","weekWords":["pour down","howl","flash","rumble","clear up"]},"writing":{"task":"Write a 4-sentence story about being caught in a sudden rainstorm.","weekWords":["pour down","howl","flash","rumble","clear up"]}},{"week":25,"weekTitle":"Caring for the Earth (愛護地球)","learn":[{"weekday":"Mon","title":"protect","pos":"v.","meaning":"保護","example":"We should all work together to protect endangered animals.","upgradeFrom":"keep safe"},{"weekday":"Tue","title":"recycle","pos":"v.","meaning":"循環再造；回收","example":"Remember to recycle plastic bottles and aluminium cans.","upgradeFrom":"reuse rubbish"},{"weekday":"Wed","title":"pollute","pos":"v.","meaning":"污染","example":"Throwing rubbish into the sea will pollute the water.","upgradeFrom":"make dirty (nature)"},{"weekday":"Thu","title":"waste","pos":"v.","meaning":"浪費","example":"Turn off the tap while brushing your teeth so you do not waste water.","upgradeFrom":"use too much"},{"weekday":"Fri","title":"environment","pos":"n.","meaning":"環境","example":"Planting more trees helps keep our environment clean and fresh.","upgradeFrom":"nature around us"}],"review":{"task":"Practise spelling *environment* carefully (en-vi-ron-ment).","weekWords":["protect","recycle","pollute","waste","environment"]},"writing":{"task":"Write 4 sentences giving tips on how students can save the Earth.","weekWords":["protect","recycle","pollute","waste","environment"]}},{"week":26,"weekTitle":"Mid-Year Adventures & Trips (半年度回顧與歷險)","learn":[{"weekday":"Mon","title":"journey","pos":"n.","meaning":"旅程；旅行","example":"The train journey across the countryside took three hours.","upgradeFrom":"trip"},{"weekday":"Tue","title":"destination","pos":"n.","meaning":"目的地","example":"After a long walk, we finally reached our destination—a hidden waterfall.","upgradeFrom":"place we are going"},{"weekday":"Wed","title":"set off","pos":"phr. v.","meaning":"出發；啟程","example":"We set off early in the morning to avoid the traffic jam.","upgradeFrom":"start a trip"},{"weekday":"Thu","title":"scenery","pos":"n.","meaning":"風景；景色","example":"I took plenty of photos of the stunning mountain scenery.","upgradeFrom":"view"},{"weekday":"Fri","title":"memorable","pos":"adj.","meaning":"值得紀念的；難忘的","example":"Camping under the stars was the most memorable part of our holiday.","upgradeFrom":"special to remember"}],"review":{"task":"Flip back through Months 1–6 and pick your **Top 10 favourite words** so far!","weekWords":["journey","destination","set off","scenery","memorable"]},"writing":{"task":"Write a 5-sentence story about an exciting day trip using this week's words plus 2 favourites from Months 1–5.","weekWords":["journey","destination","set off","scenery","memorable"]}},{"week":27,"weekTitle":"Describing Sounds (聲音描寫)","learn":[{"weekday":"Mon","title":"deafening","pos":"adj.","meaning":"震耳欲聾的","example":"A deafening bang made everyone jump out of their seats.","upgradeFrom":"extremely loud"},{"weekday":"Tue","title":"silent","pos":"adj.","meaning":"寂靜無聲的","example":"The library was silent except for the flipping of pages.","upgradeFrom":"completely quiet"},{"weekday":"Wed","title":"chirp","pos":"v.","meaning":"啾啾叫（鳥/蟲鳴）","example":"Happy sparrows chirped outside my window at dawn.","upgradeFrom":"sing (birds)"},{"weekday":"Thu","title":"rustle","pos":"v.","meaning":"發出沙沙聲","example":"Autumn leaves rustled softly in the gentle breeze.","upgradeFrom":"make a soft leaf sound"},{"weekday":"Fri","title":"echo","pos":"v.","meaning":"回響；發出回音","example":"Our laughter echoed inside the huge mountain cave.","upgradeFrom":"repeat a sound"}],"review":{"task":"Close your eyes for 30 seconds, listen to the sounds around you, and describe them in English.","weekWords":["deafening","silent","chirp","rustle","echo"]},"writing":{"task":"Write 4 sentences describing the sounds you hear in a forest or a busy street.","weekWords":["deafening","silent","chirp","rustle","echo"]}},{"week":28,"weekTitle":"Sights, Light & Colours (視覺、光線與色彩)","learn":[{"weekday":"Mon","title":"sparkling","pos":"adj.","meaning":"閃閃發光的","example":"Sunlight danced on the sparkling surface of the sea.","upgradeFrom":"shiny / bright"},{"weekday":"Tue","title":"vivid","pos":"adj.","meaning":"鮮豔的；生動的","example":"The parrot had vivid red, yellow, and blue feathers.","upgradeFrom":"very bright (colour)"},{"weekday":"Wed","title":"gloomy","pos":"adj.","meaning":"陰沉的；昏暗的","example":"The gloomy grey clouds made the afternoon feel sleepy.","upgradeFrom":"dark and sad"},{"weekday":"Thu","title":"dazzling","pos":"adj.","meaning":"耀眼的；令人目眩的","example":"The Christmas tree was covered in dazzling golden lights.","upgradeFrom":"very bright"},{"weekday":"Fri","title":"shadowy","pos":"adj.","meaning":"陰暗的；影子重重的","example":"A shadowy figure appeared at the end of the quiet alley.","upgradeFrom":"dark with shadows"}],"review":{"task":"Group the words into \"Bright/Happy sights\" and \"Dark/Spooky sights\".","weekWords":["sparkling","vivid","gloomy","dazzling","shadowy"]},"writing":{"task":"Describe either a dazzling night festival or a gloomy rainy afternoon in 4 sentences.","weekWords":["sparkling","vivid","gloomy","dazzling","shadowy"]}},{"week":29,"weekTitle":"Smells & Touch (嗅覺與觸覺)","learn":[{"weekday":"Mon","title":"fragrant","pos":"adj.","meaning":"芬芳的；清香的","example":"Mum placed a bouquet of fragrant roses on the dining table.","upgradeFrom":"smells nice"},{"weekday":"Tue","title":"foul","pos":"adj.","meaning":"惡臭的；難聞的","example":"A foul smell came from the overflowing rubbish bin.","upgradeFrom":"smells terrible"},{"weekday":"Wed","title":"fluffy","pos":"adj.","meaning":"毛茸茸的；鬆軟的","example":"I love burying my face in my fluffy white pillow.","upgradeFrom":"very soft"},{"weekday":"Thu","title":"rough","pos":"adj.","meaning":"粗糙的","example":"The tree trunk felt rough and bumpy under my fingers.","upgradeFrom":"not smooth"},{"weekday":"Fri","title":"slippery","pos":"adj.","meaning":"滑溜的；易滑倒的","example":"Walk carefully because the wet bathroom floor is slippery!","upgradeFrom":"very wet/smooth"}],"review":{"task":"Touch three objects in your room and describe their texture in English.","weekWords":["fragrant","foul","fluffy","rough","slippery"]},"writing":{"task":"Write 4 sentences describing a bakery, a garden, or a playful pet using smell and touch words.","weekWords":["fragrant","foul","fluffy","rough","slippery"]}},{"week":30,"weekTitle":"Atmosphere & Mood (氣氛與氛圍)","learn":[{"weekday":"Mon","title":"lively","pos":"adj.","meaning":"熱鬧的；生氣勃勃的","example":"The flower market was lively and full of cheerful chatter.","upgradeFrom":"busy and fun"},{"weekday":"Tue","title":"cosy","pos":"adj.","meaning":"溫暖舒適的","example":"We curled up on the cosy sofa to read stories on a cold night.","upgradeFrom":"warm and comfy"},{"weekday":"Wed","title":"mysterious","pos":"adj.","meaning":"神秘的","example":"We discovered a mysterious wooden box in Grandpa's attic.","upgradeFrom":"strange and unknown"},{"weekday":"Thu","title":"eerie","pos":"adj.","meaning":"陰森的；令人毛骨悚然的","example":"An eerie silence fell over the abandoned old house.","upgradeFrom":"creepy / spooky"},{"weekday":"Fri","title":"chaotic","pos":"adj.","meaning":"混亂的；雜亂無章的","example":"The classroom became chaotic when a bee flew through the window.","upgradeFrom":"very messy/crazy"}],"review":{"task":"Match each mood word to a story genre (e.g., ghost story -> *eerie*, adventure -> *mysterious*).","weekWords":["lively","cosy","mysterious","eerie","chaotic"]},"writing":{"task":"Write the opening 4 sentences of an imaginative story to set a strong mood.","weekWords":["lively","cosy","mysterious","eerie","chaotic"]}},{"week":31,"weekTitle":"Time & Sequence (時間與順序)","learn":[{"weekday":"Mon","title":"At first,","pos":"phr.","meaning":"起初；一開始","example":"At first, I was afraid of swimming, but soon I loved it.","upgradeFrom":"First,"},{"weekday":"Tue","title":"Meanwhile,","pos":"adv.","meaning":"與此同時","example":"I set the table; meanwhile, Dad cooked the vegetables.","upgradeFrom":"At the same time,"},{"weekday":"Wed","title":"After a while,","pos":"phr.","meaning":"過了一會兒","example":"After a while, the shy kitten came out to sniff my hand.","upgradeFrom":"Later,"},{"weekday":"Thu","title":"Immediately,","pos":"adv.","meaning":"立刻；馬上","example":"When the fire alarm rang, we immediately lined up outside.","upgradeFrom":"Very fast,"},{"weekday":"Fri","title":"Eventually,","pos":"adv.","meaning":"最終；終於","example":"We searched everywhere and eventually found the lost ring.","upgradeFrom":"Finally,"}],"review":{"task":"Tell a 3-sentence mini story out loud using *At first*, *After a while*, and *Eventually*.","weekWords":["At first,","Meanwhile,","After a while,","Immediately,","Eventually,"]},"writing":{"task":"Write a 5-sentence story about looking for something lost using all 5 connectors!","weekWords":["At first,","Meanwhile,","After a while,","Immediately,","Eventually,"]}},{"week":32,"weekTitle":"Adding Ideas (補充與遞進)","learn":[{"weekday":"Mon","title":"Besides,","pos":"adv.","meaning":"此外；而且","example":"I like cycling because it is fun. Besides, it keeps me healthy.","upgradeFrom":"Also,"},{"weekday":"Tue","title":"In addition,","pos":"phr.","meaning":"另外；除此之外","example":"The park has a playground. In addition, there is a lovely pond.","upgradeFrom":"Also,"},{"weekday":"Wed","title":"Not only... but also...","pos":"phr.","meaning":"不但……而且……","example":"Clara is not only smart but also very kind to everyone.","upgradeFrom":"...and..."},{"weekday":"Thu","title":"What is more,","pos":"phr.","meaning":"更重要的是；而且","example":"The cake looked gorgeous. What is more, it tasted heavenly!","upgradeFrom":"Even more,"},{"weekday":"Fri","title":"For instance,","pos":"phr.","meaning":"例如","example":"You can eat healthy snacks, for instance, apples or almonds.","upgradeFrom":"For example,"}],"review":{"task":"Practise making one \"Not only... but also...\" sentence about yourself.","weekWords":["Besides,","In addition,","Not only... but also...","What is more,","For instance,"]},"writing":{"task":"Write 4 sentences explaining why your favourite hobby or subject is great.","weekWords":["Besides,","In addition,","Not only... but also...","What is more,","For instance,"]}},{"week":33,"weekTitle":"Contrast & Surprise (轉折與驚喜)","learn":[{"weekday":"Mon","title":"However,","pos":"adv.","meaning":"然而；可是","example":"We planned to hike; however, it started raining heavily.","upgradeFrom":"But"},{"weekday":"Tue","title":"Although","pos":"conj.","meaning":"雖然；儘管","example":"Although the climb was tiring, the view was worth it.","upgradeFrom":"But (at start)"},{"weekday":"Wed","title":"To my surprise,","pos":"phr.","meaning":"令我驚訝的是","example":"To my surprise, my little brother finished the puzzle first!","upgradeFrom":"Surprisingly,"},{"weekday":"Thu","title":"Instead,","pos":"adv.","meaning":"反而；取而代之","example":"I did not watch TV; instead, I read a thrilling comic book.","upgradeFrom":"Not that, but..."},{"weekday":"Fri","title":"Unexpectedly,","pos":"adv.","meaning":"出乎意料地","example":"Unexpectedly, our old friend from Canada knocked on the door.","upgradeFrom":"Suddenly / By surprise"}],"review":{"task":"Remember the golden rule: NEVER use *Although* and *but* in the same sentence!","weekWords":["However,","Although","To my surprise,","Instead,","Unexpectedly,"]},"writing":{"task":"Write 4 sentences about a day that did not go as planned—in a good or funny way.","weekWords":["However,","Although","To my surprise,","Instead,","Unexpectedly,"]}},{"week":34,"weekTitle":"Cause & Effect (因果關係)","learn":[{"weekday":"Mon","title":"Therefore,","pos":"adv.","meaning":"因此；所以","example":"Max forgot his raincoat; therefore, he got wet on his way home.","upgradeFrom":"So"},{"weekday":"Tue","title":"As a result,","pos":"phr.","meaning":"結果；因此","example":"She practised every day. As a result, she won the piano contest.","upgradeFrom":"So"},{"weekday":"Wed","title":"Because of","pos":"phr.","meaning":"因為；由於（後接名詞）","example":"Because of the heavy fog, the ferry was delayed.","upgradeFrom":"Because + noun"},{"weekday":"Thu","title":"Thanks to","pos":"phr.","meaning":"多虧了；幸虧","example":"Thanks to the kind policeman, the lost boy found his mother.","upgradeFrom":"Because of (good)"},{"weekday":"Fri","title":"Since","pos":"conj.","meaning":"既然；因為","example":"Since it is sunny today, let's dry our blankets on the balcony.","upgradeFrom":"Because"}],"review":{"task":"Check the difference: *Because of* + noun (e.g., the rain); *Since* + full clause (e.g., it is raining).","weekWords":["Therefore,","As a result,","Because of","Thanks to","Since"]},"writing":{"task":"Write 4 sentences explaining how a good habit or kind action led to a happy result.","weekWords":["Therefore,","As a result,","Because of","Thanks to","Since"]}},{"week":35,"weekTitle":"Concluding Stories (為文章作結)","learn":[{"weekday":"Mon","title":"All in all,","pos":"phr.","meaning":"總而言之","example":"All in all, it was the best birthday party I have ever had.","upgradeFrom":"In the end,"},{"weekday":"Tue","title":"From that day on,","pos":"phr.","meaning":"從那天起","example":"From that day on, Tom never lied to his parents again.","upgradeFrom":"After that day,"},{"weekday":"Wed","title":"In the end,","pos":"phr.","meaning":"最後；終於","example":"In the end, both teams shook hands and became friends.","upgradeFrom":"Finally,"},{"weekday":"Thu","title":"To sum up,","pos":"phr.","meaning":"總結來說","example":"To sum up, keeping a pet takes love and responsibility.","upgradeFrom":"Lastly,"},{"weekday":"Fri","title":"I will never forget...","pos":"phr.","meaning":"我永遠不會忘記……","example":"I will never forget the kindness that stranger showed me.","upgradeFrom":"I will remember..."}],"review":{"task":"Pick which ending works best for a story (*From that day on*) vs. an essay (*To sum up*).","weekWords":["All in all,","From that day on,","In the end,","To sum up,","I will never forget..."]},"writing":{"task":"Write 3 different \"super endings\" for imaginary stories using this week's phrases.","weekWords":["All in all,","From that day on,","In the end,","To sum up,","I will never forget..."]}},{"week":36,"weekTitle":"Everyday Actions (日常動作片語)","learn":[{"weekday":"Mon","title":"come across","pos":"phr. v.","meaning":"偶然發現；偶遇","example":"While cleaning the cupboard, I came across my baby photos.","upgradeFrom":"find by chance"},{"weekday":"Tue","title":"look forward to","pos":"phr. v.","meaning":"期待；盼望","example":"I look forward to visiting my cousins during the summer holiday.","upgradeFrom":"cannot wait for"},{"weekday":"Wed","title":"run out of","pos":"phr. v.","meaning":"用光；耗盡","example":"Oh no! We have run out of eggs to bake the birthday cake.","upgradeFrom":"have no more"},{"weekday":"Thu","title":"show off","pos":"phr. v.","meaning":"炫耀；賣弄","example":"Nobody liked it when Ryan showed off his expensive new watch.","upgradeFrom":"boast"},{"weekday":"Fri","title":"turn down","pos":"phr. v.","meaning":"拒絕；調低（音量）","example":"She politely turned down the extra slice of cake because she was full.","upgradeFrom":"say no / lower"}],"review":{"task":"Grammar tip: After *look forward to*, use **-ing** or a noun (e.g., *look forward to seeing you*).","weekWords":["come across","look forward to","run out of","show off","turn down"]},"writing":{"task":"Write 4 sentences about preparing for a holiday or party.","weekWords":["come across","look forward to","run out of","show off","turn down"]}},{"week":37,"weekTitle":"Problems & Solutions (問題與解決)","learn":[{"weekday":"Mon","title":"figure out","pos":"phr. v.","meaning":"想出；弄明白","example":"After thinking hard, Kelly figured out the riddle.","upgradeFrom":"solve / understand"},{"weekday":"Tue","title":"give up","pos":"phr. v.","meaning":"放棄","example":"Even though the hill was steep, we refused to give up.","upgradeFrom":"stop trying"},{"weekday":"Wed","title":"break down","pos":"phr. v.","meaning":"拋錨；發生故障","example":"Our school bus broke down halfway to the museum.","upgradeFrom":"stop working"},{"weekday":"Thu","title":"put out","pos":"phr. v.","meaning":"撲滅（火）","example":"The firefighters arrived quickly and put out the kitchen fire.","upgradeFrom":"stop a fire"},{"weekday":"Fri","title":"sort out","pos":"phr. v.","meaning":"解決；整理好","example":"Miss Lee helped the two classmates sort out their misunderstanding.","upgradeFrom":"fix a problem"}],"review":{"task":"Quiz yourself on the past tense: *figured out, gave up, broke down, put out, sorted out*.","weekWords":["figure out","give up","break down","put out","sort out"]},"writing":{"task":"Write a 4-sentence mini story about a problem that happened on a trip and how it was solved.","weekWords":["figure out","give up","break down","put out","sort out"]}},{"week":38,"weekTitle":"Emotions & Reactions (情緒與反應)","learn":[{"weekday":"Mon","title":"burst into laughter","pos":"phr.","meaning":"突然大笑起來","example":"When the clown slipped on a toy banana, everyone burst into laughter.","upgradeFrom":"laugh suddenly"},{"weekday":"Tue","title":"burst into tears","pos":"phr.","meaning":"突然放聲大哭","example":"The toddler burst into tears when his balloon floated away.","upgradeFrom":"cry suddenly"},{"weekday":"Wed","title":"calm down","pos":"phr. v.","meaning":"冷靜下來","example":"Take a deep breath and calm down before you speak.","upgradeFrom":"stop being angry/scared"},{"weekday":"Thu","title":"cheer up","pos":"phr. v.","meaning":"振作起來；使高興","example":"I drew a funny card to cheer my sick friend up.","upgradeFrom":"become happier"},{"weekday":"Fri","title":"freak out","pos":"phr. v.","meaning":"嚇壞；驚慌失措","example":"My sister freaked out when she saw a huge cockroach in the kitchen!","upgradeFrom":"panic"}],"review":{"task":"Compare *burst into laughter* and *burst into tears*—notice how expressive \"burst into\" is!","weekWords":["burst into laughter","burst into tears","calm down","cheer up","freak out"]},"writing":{"task":"Write 4 sentences about a funny or dramatic surprise at home.","weekWords":["burst into laughter","burst into tears","calm down","cheer up","freak out"]}},{"week":39,"weekTitle":"Social Interactions (社交與相處)","learn":[{"weekday":"Mon","title":"make up with","pos":"phr. v.","meaning":"與……和好","example":"After saying sorry, Noah made up with his best friend.","upgradeFrom":"be friends again"},{"weekday":"Tue","title":"count on","pos":"phr. v.","meaning":"依靠；信賴","example":"You can always count on Mum to help when you are in trouble.","upgradeFrom":"trust to help"},{"weekday":"Wed","title":"bump into","pos":"phr. v.","meaning":"偶遇；不期而遇","example":"We bumped into our English teacher at the supermarket!","upgradeFrom":"meet by chance"},{"weekday":"Thu","title":"look after","pos":"phr. v.","meaning":"照顧；照料","example":"My aunt came over to look after us while our parents worked late.","upgradeFrom":"take care of"},{"weekday":"Fri","title":"let someone down","pos":"phr. v.","meaning":"令某人失望","example":"I practised my lines hard because I did not want to let my team down.","upgradeFrom":"disappoint"}],"review":{"task":"Make a sentence about a friend using *count on* or *bump into*.","weekWords":["make up with","count on","bump into","look after","let someone down"]},"writing":{"task":"Write 4 sentences about a small argument between friends that had a happy ending.","weekWords":["make up with","count on","bump into","look after","let someone down"]}},{"week":40,"weekTitle":"Classic Similes (經典明喻)","learn":[{"weekday":"Mon","title":"as quiet as a mouse","pos":"","meaning":"像老鼠一樣安靜","example":"The children sat as quiet as a mouse while the storyteller spoke.","upgradeFrom":"very quiet"},{"weekday":"Tue","title":"as busy as a bee","pos":"","meaning":"像蜜蜂一樣忙碌","example":"Mum was as busy as a bee preparing for the family party.","upgradeFrom":"very busy"},{"weekday":"Wed","title":"as light as a feather","pos":"","meaning":"輕如鴻毛；非常輕","example":"This new schoolbag feels as light as a feather!","upgradeFrom":"very light"},{"weekday":"Thu","title":"as proud as a peacock","pos":"","meaning":"像孔雀一樣驕傲自豪","example":"Leo stood as proud as a peacock holding his gold medal.","upgradeFrom":"very proud"},{"weekday":"Fri","title":"as hungry as a wolf","pos":"","meaning":"餓得像狼一樣","example":"After a two-hour football match, I was as hungry as a wolf.","upgradeFrom":"starving / very hungry"}],"review":{"task":"Cover the animal/object and fill in the blank: as quiet as a ___, as busy as a ___.","weekWords":["as quiet as a mouse","as busy as a bee","as light as a feather","as proud as a peacock","as hungry as a wolf"]},"writing":{"task":"Write 4 sentences about your day using at least 3 similes!","weekWords":["as quiet as a mouse","as busy as a bee","as light as a feather","as proud as a peacock","as hungry as a wolf"]}},{"week":41,"weekTitle":"Animal Idioms (有趣的動物習語)","learn":[{"weekday":"Mon","title":"rain cats and dogs","pos":"","meaning":"下傾盆大雨","example":"We stayed indoors because it was raining cats and dogs.","upgradeFrom":"rain very heavily"},{"weekday":"Tue","title":"butterflies in one's stomach","pos":"","meaning":"心裡七上八下；緊張","example":"I had butterflies in my stomach before my first piano exam.","upgradeFrom":"feel very nervous"},{"weekday":"Wed","title":"a piece of cake","pos":"","meaning":"小菜一碟；輕而易舉","example":"After revising every day, the English quiz was a piece of cake.","upgradeFrom":"very easy"},{"weekday":"Thu","title":"hold your horses","pos":"","meaning":"慢著；別急","example":"\"Hold your horses! Put on your shoes before rushing out,\" Dad laughed.","upgradeFrom":"wait / be patient"},{"weekday":"Fri","title":"early bird","pos":"","meaning":"早起的人","example":"Grandpa is an early bird who wakes up at six every morning.","upgradeFrom":"someone who wakes early"}],"review":{"task":"Draw a funny cartoon picture for your favourite idiom from this week!","weekWords":["rain cats and dogs","butterflies in one's stomach","a piece of cake","hold your horses","early bird"]},"writing":{"task":"Write 4 sentences about a school morning or test day using at least 2 idioms.","weekWords":["rain cats and dogs","butterflies in one's stomach","a piece of cake","hold your horses","early bird"]}},{"week":42,"weekTitle":"Feeling & Reaction Idioms (心情與反應習語)","learn":[{"weekday":"Mon","title":"on cloud nine","pos":"","meaning":"樂翻天；高興極了","example":"Zoe was on cloud nine when she heard we were going to Disneyland.","upgradeFrom":"extremely happy"},{"weekday":"Tue","title":"over the moon","pos":"","meaning":"欣喜若狂","example":"Our coach was over the moon about our victory.","upgradeFrom":"thrilled"},{"weekday":"Wed","title":"down in the dumps","pos":"","meaning":"垂頭喪氣；悶悶不樂","example":"Ben felt down in the dumps after losing his favourite pen.","upgradeFrom":"feeling sad"},{"weekday":"Thu","title":"lose one's temper","pos":"","meaning":"發脾氣；動怒","example":"Try not to lose your temper when things go wrong.","upgradeFrom":"get very angry"},{"weekday":"Fri","title":"frozen to the spot","pos":"","meaning":"嚇呆了；定在原地","example":"I was frozen to the spot when a giant spider dropped onto my desk.","upgradeFrom":"too scared/shocked to move"}],"review":{"task":"Sort the 5 idioms into Happy, Sad, Angry, and Scared.","weekWords":["on cloud nine","over the moon","down in the dumps","lose one's temper","frozen to the spot"]},"writing":{"task":"Write a short diary entry describing a roller-coaster day of emotions!","weekWords":["on cloud nine","over the moon","down in the dumps","lose one's temper","frozen to the spot"]}},{"week":43,"weekTitle":"Effort, Speed & Luck Idioms (努力、速度與運氣習語)","learn":[{"weekday":"Mon","title":"in the blink of an eye","pos":"","meaning":"一眨眼之間；瞬間","example":"In the blink of an eye, the stray cat vanished over the wall.","upgradeFrom":"very quickly"},{"weekday":"Tue","title":"give it a shot","pos":"","meaning":"試一試","example":"I had never tried ice-skating, so I decided to give it a shot.","upgradeFrom":"try"},{"weekday":"Wed","title":"practice makes perfect","pos":"","meaning":"熟能生巧","example":"Remember, practice makes perfect—keep practising your handwriting!","upgradeFrom":"practising makes you great"},{"weekday":"Thu","title":"out of the blue","pos":"","meaning":"出乎意料地；突然","example":"Out of the blue, my uncle arrived with a box of mango pudding.","upgradeFrom":"suddenly / unexpectedly"},{"weekday":"Fri","title":"better late than never","pos":"","meaning":"遲做總比不做好","example":"Tim finally tidied his desk on Sunday night—better late than never!","upgradeFrom":"good to do even if late"}],"review":{"task":"Quiz yourself: Which idiom means \"suddenly\"? Which means \"very quickly\"?","weekWords":["in the blink of an eye","give it a shot","practice makes perfect","out of the blue","better late than never"]},"writing":{"task":"Write 4 sentences about trying a new sport, hobby, or food for the first time.","weekWords":["in the blink of an eye","give it a shot","practice makes perfect","out of the blue","better late than never"]}},{"week":44,"weekTitle":"Sudden Events (突發事件)","learn":[{"weekday":"Mon","title":"All of a sudden,","pos":"phr.","meaning":"突然間","example":"All of a sudden, the lights in the whole building went out!","upgradeFrom":"Suddenly,"},{"weekday":"Tue","title":"Without warning,","pos":"phr.","meaning":"毫無預警地","example":"Without warning, a gust of wind blew my hat into the river.","upgradeFrom":"Suddenly,"},{"weekday":"Wed","title":"slip and stumble","pos":"phr.","meaning":"滑倒並踉蹌","example":"Because of the wet stairs, the boy slipped and stumbled.","upgradeFrom":"fall / trip"},{"weekday":"Thu","title":"disaster","pos":"n.","meaning":"災難；大麻煩","example":"Dropping the birthday cake on the floor seemed like a total disaster.","upgradeFrom":"terrible event"},{"weekday":"Fri","title":"panic","pos":"v. / n.","meaning":"驚慌；恐慌","example":"Do not panic if you get separated from your parents in a mall.","upgradeFrom":"get very scared"}],"review":{"task":"Practise starting an exciting sentence with *All of a sudden,* and *Without warning,*.","weekWords":["All of a sudden,","Without warning,","slip and stumble","disaster","panic"]},"writing":{"task":"Write the exciting middle (problem!) of an adventure story in 4–5 sentences.","weekWords":["All of a sudden,","Without warning,","slip and stumble","disaster","panic"]}},{"week":45,"weekTitle":"Suspense & Worry (懸疑與擔憂)","learn":[{"weekday":"Mon","title":"heart pounded","pos":"phr.","meaning":"心怦怦直跳","example":"My heart pounded as I stepped onto the dark stage.","upgradeFrom":"heart beat fast"},{"weekday":"Tue","title":"hold one's breath","pos":"phr.","meaning":"屏住呼吸","example":"Everyone held their breath as the juggler tossed five balls in the air.","upgradeFrom":"stop breathing (tense)"},{"weekday":"Wed","title":"vanish","pos":"v.","meaning":"消失無蹤","example":"The magician waved his cape and the rabbit vanished!","upgradeFrom":"disappear"},{"weekday":"Thu","title":"desperate","pos":"adj.","meaning":"焦急萬分的；絕望的","example":"We were desperate to find our lost dog before nightfall.","upgradeFrom":"very worried/needy"},{"weekday":"Fri","title":"hesitate","pos":"v.","meaning":"猶豫；遲疑","example":"Lucy hesitated for a second before jumping into the deep pool.","upgradeFrom":"pause / unsure"}],"review":{"task":"Read aloud the difference between *vanish* (disappear) and *hesitate* (pause).","weekWords":["heart pounded","hold one's breath","vanish","desperate","hesitate"]},"writing":{"task":"Write 4 suspenseful sentences about opening a mysterious door or searching for a lost pet.","weekWords":["heart pounded","hold one's breath","vanish","desperate","hesitate"]}},{"week":46,"weekTitle":"Bravery & Kindness (勇敢與仁慈)","learn":[{"weekday":"Mon","title":"without hesitation","pos":"phr.","meaning":"毫不猶豫地","example":"Without hesitation, the passer-by helped the elderly lady pick up her oranges.","upgradeFrom":"right away / bravely"},{"weekday":"Tue","title":"rescue","pos":"v.","meaning":"營救；救出","example":"Lifeguards quickly swam out to rescue the tired swimmer.","upgradeFrom":"save"},{"weekday":"Wed","title":"compassionate","pos":"adj.","meaning":"有同情心的；仁慈的","example":"The compassionate girl shared her umbrella with a stranger.","upgradeFrom":"very kind / caring"},{"weekday":"Thu","title":"act of kindness","pos":"phr.","meaning":"善舉；好心之舉","example":"Even a small act of kindness can brighten someone's whole day.","upgradeFrom":"kind thing to do"},{"weekday":"Fri","title":"grateful","pos":"adj.","meaning":"感激的；感恩的","example":"I am deeply grateful to my teachers for guiding me patiently.","upgradeFrom":"very thankful"}],"review":{"task":"Notice the pair: Week 45 *hesitate* vs Week 46 *without hesitation*!","weekWords":["without hesitation","rescue","compassionate","act of kindness","grateful"]},"writing":{"task":"Write a 5-sentence story about a character who does a brave or kind deed.","weekWords":["without hesitation","rescue","compassionate","act of kindness","grateful"]}},{"week":47,"weekTitle":"Apologising & Forgiving (道歉與原諒)","learn":[{"weekday":"Mon","title":"apologise sincerely","pos":"phr.","meaning":"真誠地道歉","example":"Ethan apologised sincerely for breaking his friend's ruler.","upgradeFrom":"say sorry nicely"},{"weekday":"Tue","title":"admit one's mistake","pos":"phr.","meaning":"承認錯誤","example":"It takes courage to admit your mistake honestly.","upgradeFrom":"say \"I was wrong\""},{"weekday":"Wed","title":"forgive","pos":"v.","meaning":"原諒；寬恕","example":"Mum smiled and forgave me after I promised to be more careful.","upgradeFrom":"not stay angry"},{"weekday":"Thu","title":"guilty","pos":"adj.","meaning":"內疚的；有罪惡感的","example":"I felt guilty for eating my brother's last chocolate biscuit.","upgradeFrom":"feel bad about wrong"},{"weekday":"Fri","title":"relieved","pos":"adj.","meaning":"鬆了一口氣的；放心的","example":"I felt hugely relieved when the doctor said my puppy was fine.","upgradeFrom":"happy the worry is over"}],"review":{"task":"Trace the emotion journey: *guilty* -> *admit mistake* -> *apologise sincerely* -> *forgive* -> *relieved*!","weekWords":["apologise sincerely","admit one's mistake","forgive","guilty","relieved"]},"writing":{"task":"Write a short story where someone makes a mistake, apologises, and feels relieved.","weekWords":["apologise sincerely","admit one's mistake","forgive","guilty","relieved"]}},{"week":48,"weekTitle":"Lessons Learned (吸取教訓)","learn":[{"weekday":"Mon","title":"learn a valuable lesson","pos":"phr.","meaning":"學到寶貴的一課","example":"After getting lost in the mall, Amy learned a valuable lesson about staying close to Mum.","upgradeFrom":"learn something important"},{"weekday":"Tue","title":"honesty","pos":"n.","meaning":"誠實","example":"The principal praised Jacob for his honesty when he returned the wallet.","upgradeFrom":"telling the truth"},{"weekday":"Wed","title":"patience","pos":"n.","meaning":"耐心","example":"Growing sunflowers requires sunlight, water, and plenty of patience.","upgradeFrom":"waiting calmly"},{"weekday":"Thu","title":"realise","pos":"v.","meaning":"意識到；領悟到","example":"I realised that teamwork is much more powerful than working alone.","upgradeFrom":"understand suddenly"},{"weekday":"Fri","title":"promise","pos":"v. / n.","meaning":"承諾；保證","example":"I promised myself that I would always check my homework carefully.","upgradeFrom":"say you will do it"}],"review":{"task":"Practise spelling *valuable*, *honesty*, and *patience*.","weekWords":["learn a valuable lesson","honesty","patience","realise","promise"]},"writing":{"task":"Write 4 sentences ending a story with a strong moral or lesson learned.","weekWords":["learn a valuable lesson","honesty","patience","realise","promise"]}},{"week":49,"weekTitle":"Fantasy & Imagination (奇幻與想像力)","learn":[{"weekday":"Mon","title":"enchanted","pos":"adj.","meaning":"施了魔法的；迷人的","example":"The hero stepped into an enchanted forest where trees could talk.","upgradeFrom":"magical"},{"weekday":"Tue","title":"glittering","pos":"adj.","meaning":"閃閃生輝的","example":"A glittering treasure chest rested at the bottom of the cave.","upgradeFrom":"sparkly"},{"weekday":"Wed","title":"magnificent","pos":"adj.","meaning":"壯麗的；宏偉的","example":"A magnificent golden castle floated high above the clouds.","upgradeFrom":"super grand/beautiful"},{"weekday":"Thu","title":"extraordinary","pos":"adj.","meaning":"非凡的；了不起的","example":"The ordinary-looking compass had an extraordinary secret power.","upgradeFrom":"very special"},{"weekday":"Fri","title":"transform","pos":"v.","meaning":"轉變；變形","example":"With a wave of the wand, the pumpkin transformed into a carriage.","upgradeFrom":"change completely"}],"review":{"task":"Say *extraordinary* slowly in syllables: ex-tra-or-di-na-ry.","weekWords":["enchanted","glittering","magnificent","extraordinary","transform"]},"writing":{"task":"Write a 5-sentence fantasy mini-story about discovering a magical object!","weekWords":["enchanted","glittering","magnificent","extraordinary","transform"]}},{"week":50,"weekTitle":"Polite Phrases for Letters & Emails (書信與電郵的禮貌用語)","learn":[{"weekday":"Mon","title":"How have you been?","pos":"","meaning":"你最近過得好嗎？","example":"Dear May, How have you been? I hope you are enjoying your new school!","usage":"Greeting a friend"},{"weekday":"Tue","title":"I am writing to...","pos":"","meaning":"我寫這封信是為了……","example":"I am writing to invite you to my ninth birthday party this Saturday.","usage":"Stating purpose"},{"weekday":"Wed","title":"Would you like to...?","pos":"","meaning":"你想不想……？","example":"Would you like to come to the science museum with my family?","usage":"Polite invitation"},{"weekday":"Thu","title":"Thank you so much for...","pos":"","meaning":"非常感謝你……","example":"Thank you so much for sending me that lovely storybook.","usage":"Showing gratitude"},{"weekday":"Fri","title":"Write back soon!","pos":"","meaning":"請早點回信！","example":"I cannot wait to hear your news. Write back soon!","usage":"Friendly closing"}],"review":{"task":"Read all 5 phrases in order—notice they form the skeleton of a perfect letter!","weekWords":["How have you been?","I am writing to...","Would you like to...?","Thank you so much for...","Write back soon!"]},"writing":{"task":"Write a short, polite letter or email (5–6 sentences) inviting a friend to an outing.","weekWords":["How have you been?","I am writing to...","Would you like to...?","Thank you so much for...","Write back soon!"]}},{"week":51,"weekTitle":"Expressing Opinions Clearly (清晰表達意見)","learn":[{"weekday":"Mon","title":"In my opinion,","pos":"phr.","meaning":"依我看；我認為","example":"In my opinion, reading is the best hobby for children.","upgradeFrom":"I think"},{"weekday":"Tue","title":"I strongly believe that...","pos":"","meaning":"我堅信……","example":"I strongly believe that every student should learn how to swim.","upgradeFrom":"I really think"},{"weekday":"Wed","title":"prefer... to...","pos":"phr.","meaning":"比起……更喜歡……","example":"I prefer fresh fruit to sugary sweets.","upgradeFrom":"like more than"},{"weekday":"Thu","title":"beneficial","pos":"adj.","meaning":"有益的；有好處的","example":"Playing team sports is beneficial for both our body and mind.","upgradeFrom":"very good/helpful"},{"weekday":"Fri","title":"recommend","pos":"v.","meaning":"推薦；建議","example":"I highly recommend this adventure book to anyone who loves mysteries.","upgradeFrom":"say it is good"}],"review":{"task":"Grammar check: Use **to** with *prefer* (e.g., *prefer cats **to** dogs*, NOT *than*).","weekWords":["In my opinion,","I strongly believe that...","prefer... to...","beneficial","recommend"]},"writing":{"task":"Write a 5-sentence book or movie review giving your opinion and recommendation!","weekWords":["In my opinion,","I strongly believe that...","prefer... to...","beneficial","recommend"]}},{"week":52,"weekTitle":"Young Author's Master Toolkit (小作家終極工具箱)","learn":[{"weekday":"Mon","title":"unbelievable","pos":"adj.","meaning":"難以置信的","example":"Seeing a real shooting star was an unbelievable sight!","upgradeFrom":"amazing / hard to believe"},{"weekday":"Tue","title":"vividly","pos":"adv.","meaning":"清晰地；生動地","example":"I still vividly remember my very first day of Primary 3.","upgradeFrom":"very clearly (remember)"},{"weekday":"Wed","title":"inspire","pos":"v.","meaning":"啟發；鼓舞","example":"That brave paralympic athlete inspired me never to give up.","upgradeFrom":"give great ideas/hope"},{"weekday":"Thu","title":"confident","pos":"adj.","meaning":"有自信的","example":"After a year of practice, I feel much more confident in writing English!","upgradeFrom":"sure of oneself"},{"weekday":"Fri","title":"accomplishment","pos":"n.","meaning":"成就；成績","example":"Finishing this one-year vocabulary plan is a wonderful accomplishment!","upgradeFrom":"big success"}],"review":{"task":"Look back at your notebook from Week 1 to Week 52. Pick **10 words** you want to use in your final masterpiece!","weekWords":["unbelievable","vividly","inspire","confident","accomplishment"],"yearEnd":true},"writing":{"task":"Write a **100–150 word composition** titled *\"My Most Unforgettable Day\"* (or *\"A Magical Adventure\"*) using at least **8 upgraded words/phrases** from across the year. Celebrate your hard work—you are now a confident young English writer!","weekWords":["unbelievable","vividly","inspire","confident","accomplishment"],"graduation":true}}]};
